<?php
class ProductionBatch extends Model
{
 protected $table='production_batches';
 private function baseSelect(){return "SELECT pb.*,mf.quantity_kg feed_quantity_kg,mf.authorized_quantity_kg,mf.silo_id,s.name silo_name,m.name machine_name,m.code machine_code,p.name product_name,u.name agent_name,v.name validator_name,bss.document_number bss_number FROM production_batches pb JOIN machine_feeds mf ON mf.id=pb.machine_feed_id JOIN silos s ON s.id=mf.silo_id JOIN machines m ON m.id=mf.machine_id JOIN products p ON p.id=pb.product_id LEFT JOIN users u ON u.id=pb.created_by LEFT JOIN users v ON v.id=pb.validated_by LEFT JOIN documents bss ON bss.id=mf.bss_document_id";}
 public function allDetailed(){$p=[];$scope=Auth::siteClause('pb.site_id',$p);return$this->query($this->baseSelect()." WHERE pb.deleted_at IS NULL{$scope} ORDER BY pb.started_at DESC",$p)->fetchAll();}
 public function pendingForSelect(){$p=[];$scope=Auth::siteClause('pb.site_id',$p);return$this->query($this->baseSelect()." WHERE pb.status IN('pending','in_progress') AND pb.deleted_at IS NULL{$scope} ORDER BY pb.started_at",$p)->fetchAll();}
 public function findDetailed($id){$p=['id'=>$id];$scope=Auth::siteClause('pb.site_id',$p);$r=$this->query($this->baseSelect()." WHERE pb.id=:id AND pb.deleted_at IS NULL{$scope} LIMIT 1",$p)->fetch();if($r){$r['waste_lines']=$this->query('SELECT pwl.*,wt.code,wt.name FROM production_waste_lines pwl JOIN waste_types wt ON wt.id=pwl.waste_type_id WHERE pwl.production_batch_id=:id AND pwl.deleted_at IS NULL ORDER BY wt.name',['id'=>$id])->fetchAll();}return$r;}
 public function directoryWasteLines(){$p=[];$scope=Auth::siteClause('pb.site_id',$p);$rows=$this->query("SELECT pwl.*,wt.name FROM production_waste_lines pwl JOIN production_batches pb ON pb.id=pwl.production_batch_id JOIN waste_types wt ON wt.id=pwl.waste_type_id WHERE pb.deleted_at IS NULL AND pwl.deleted_at IS NULL{$scope} ORDER BY wt.name",$p)->fetchAll();$grouped=[];foreach($rows as$r)$grouped[$r['production_batch_id']][]=$r;return$grouped;}
 public function wasteTypes(){return$this->query("SELECT id,code,name FROM waste_types WHERE status='active' AND deleted_at IS NULL ORDER BY name")->fetchAll();}
 public function tolerance($site=null){ $site=$site??Auth::currentSiteId();if($site===null)return 2.0;$v=$this->query('SELECT tolerance_percent FROM production_variance_settings WHERE site_id=:site',['site'=>$site])->fetchColumn();return$v!==false?(float)$v:2.0; }
 public function updateTolerance($value,array$user){$site=Auth::requireCurrentSite();if(!is_numeric($value)||!is_finite((float)$value))throw new RuntimeException('Saisissez une tolérance numérique.');$value=(float)$value;if($value<0||$value>100)throw new RuntimeException('Tolérance comprise entre 0 et 100%.');$this->db->beginTransaction();try{$this->query('INSERT INTO production_variance_settings(site_id,tolerance_percent,updated_by) VALUES(:site,:value,:user) ON DUPLICATE KEY UPDATE tolerance_percent=:value2,updated_by=:user2',['site'=>$site,'value'=>$value,'user'=>$user['id'],'value2'=>$value,'user2'=>$user['id']]);$this->logActivity('update_tolerance','production','production_variance_settings',$site,'Modification de la tolérance d’écart.',null,['tolerance_percent'=>$value],$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}

 public function submitResults(array$data,array$user){$this->db->beginTransaction();try{$b=$this->lockBatch($data['production_batch_id']);if(!$b)throw new RuntimeException('Lot introuvable.');Auth::requireSiteAccess($b['site_id']);$correction=in_array($b['status'],['results_submitted','pending_additional_approval'],true);
if(!in_array($b['status'],['pending','in_progress','results_submitted','pending_additional_approval'],true))throw new RuntimeException('Ce lot est validé ou annulé : ses résultats ne peuvent plus être modifiés.');
if(isset($data['version'])&&!hash_equals(self::version($b),(string)$data['version']))throw new RuntimeException('Ce lot a été modifié entre-temps. Actualisez la liste avant de réessayer.');
if($correction&&trim($data['correction_reason']??'')==='')throw new RuntimeException('Indiquez le motif de correction des résultats.');
$raw=str_replace('T',' ',trim($data['ended_at']??''));$format=strlen($raw)===16?'Y-m-d H:i':'Y-m-d H:i:s';$date=DateTimeImmutable::createFromFormat('!'.$format,$raw);
if(!$date||$date->format($format)!==$raw)throw new RuntimeException('La date et l’heure de fin sont invalides.');
if($date->format('Y-m-d H:i:s')<$b['started_at'])throw new RuntimeException('La fin de production ne peut pas précéder le début du lot.');$data['ended_at']=$date->format('Y-m-d H:i:s');
if(!is_numeric($data['output_quantity_kg'])||!is_finite((float)$data['output_quantity_kg'])||(float)$data['output_quantity_kg']>999999999.999)throw new RuntimeException('La quantité de farine est invalide.');$loaded=(float)$b['actual_input_quantity_kg'];$flour=round((float)$data['output_quantity_kg'],3);$waste=0;$lines=$data['waste_lines']??[];foreach($lines as$type=>$qty){if(!ctype_digit((string)$type)||!is_numeric($qty)||!is_finite((float)$qty)||(float)$qty<0||(float)$qty>999999999.999)throw new RuntimeException('Ligne de déchet invalide.');$validType=$this->query("SELECT id FROM waste_types WHERE id=? AND status='active' AND deleted_at IS NULL",[$type])->fetchColumn();if(!$validType)throw new RuntimeException('Un type de déchet n’est plus disponible. Actualisez la page.');$lines[$type]=round((float)$qty,3);$waste+=$lines[$type];}if($loaded<=0||$flour<0)throw new RuntimeException('Quantités invalides.');$waste=round($waste,3);$variance=round($loaded-$flour-$waste,3);$pct=$variance/$loaded*100;$yield=$flour/$loaded*100;$tol=(float)$data['variance_tolerance_percent'];if($tol<0)throw new RuntimeException('Tolérance invalide.');$over=abs($pct)>$tol;if($over&&trim($data['variance_justification']??'')==='')throw new RuntimeException('Une justification est obligatoire lorsque l’écart dépasse la tolérance.');$status=$over?'pending_additional_approval':'results_submitted';$this->query('UPDATE production_batches SET output_quantity_kg=:flour,waste_quantity_kg=:waste,yield_percent=:yield,variance_quantity_kg=:variance,variance_percent=:pct,variance_tolerance_percent=:tol,variance_justification=:justification,ended_at=:ended,status=:status,results_submitted_by=:user,results_submitted_at=NOW() WHERE id=:id',['flour'=>$flour,'waste'=>$waste,'yield'=>$yield,'variance'=>$variance,'pct'=>$pct,'tol'=>$tol,'justification'=>trim($data['variance_justification']??'')?:null,'ended'=>$data['ended_at'],'status'=>$status,'user'=>$user['id'],'id'=>$b['id']]);$this->query('DELETE FROM production_waste_lines WHERE production_batch_id=:id',['id'=>$b['id']]);foreach($lines as$type=>$qty){if((float)$qty>0)$this->query('INSERT INTO production_waste_lines(production_batch_id,waste_type_id,quantity_kg) VALUES(:batch,:type,:qty)',['batch'=>$b['id'],'type'=>$type,'qty'=>$qty]);}$this->logActivity('submit_results','production','production_batches',$b['id'],'Saisie des résultats de production.',$b,['motif_correction'=>$data['correction_reason']??null,'farine'=>$flour,'dechets'=>$waste,'ecart'=>$variance,'ecart_percent'=>$pct,'status'=>$status],$user);$this->db->commit();return$status;}catch(Exception$e){$this->db->rollBack();throw$e;}}

 public function validateProduction(array$data,array$user){if(isset($data['output_quantity_kg'])){$row=$this->query('SELECT status FROM production_batches WHERE id=:id',['id'=>$data['production_batch_id']])->fetch();if($row&&in_array($row['status'],['pending','in_progress'],true)){$type=$this->query("SELECT id FROM waste_types WHERE code='SON' LIMIT 1")->fetchColumn();$this->submitResults(['production_batch_id'=>$data['production_batch_id'],'output_quantity_kg'=>$data['output_quantity_kg'],'waste_lines'=>[$type=>$data['waste_quantity_kg']],'variance_tolerance_percent'=>$data['variance_tolerance_percent']??100,'variance_justification'=>$data['variance_justification']??'Compatibilité historique','ended_at'=>$data['ended_at']],$user);}}
  $this->db->beginTransaction();try{$b=$this->lockBatch($data['production_batch_id']);if(!$b)throw new RuntimeException('Lot introuvable.');Auth::requireSiteAccess($b['site_id']);require_once dirname(__DIR__).'/services/AuthorizationService.php';(new AuthorizationService($this->db))->assertCanValidateRecord($user['id']??null,'production',$b);if(isset($data['version'])&&!hash_equals(self::version($b),(string)$data['version']))throw new RuntimeException('Les résultats ont changé. Consultez les nouvelles valeurs avant de valider.');if(!in_array($b['status'],['results_submitted','pending_additional_approval'],true))throw new RuntimeException('Lot non soumis, déjà validé ou non validable.');if($b['status']==='pending_additional_approval'&&(int)$b['results_submitted_by']===(int)$user['id'])throw new RuntimeException('L’approbation complémentaire exige un autre utilisateur.');$flourProduct=$this->productId('FARINE-MAIS');$before=$this->latestProductStock($flourProduct,$b['site_id']);$after=$before+(float)$b['output_quantity_kg'];$this->query("INSERT INTO bulk_flour_stocks(site_id,product_id,production_batch_id,quantity_kg,status) VALUES(:site,:product,:batch,:qty,'active')",['site'=>$b['site_id'],'product'=>$flourProduct,'batch'=>$b['id'],'qty'=>$b['output_quantity_kg']]);$movement=null;if((float)$b['output_quantity_kg']>0){$this->query("INSERT INTO stock_movements(site_id,product_id,finished_stock_id,distribution_id,movement_type,quantity_bags,quantity_kg,stock_before_kg,stock_after_kg,movement_at,status,created_by) VALUES(:site,:product,NULL,NULL,'in',0,:qty,:before,:after,:at,'validated',:user)",['site'=>$b['site_id'],'product'=>$flourProduct,'qty'=>$b['output_quantity_kg'],'before'=>$before,'after'=>$after,'at'=>$b['ended_at'],'user'=>$user['id']]);$movement=$this->db->lastInsertId();}$wasteSite=$this->siteId('PELL');$lines=$this->query('SELECT pwl.*,wt.product_id FROM production_waste_lines pwl JOIN waste_types wt ON wt.id=pwl.waste_type_id WHERE pwl.production_batch_id=:id AND pwl.deleted_at IS NULL FOR UPDATE',['id'=>$b['id']])->fetchAll();foreach($lines as$line)$this->query("INSERT INTO waste_stocks(site_id,product_id,waste_type_id,production_batch_id,quantity_kg,status) VALUES(:site,:product,:type,:batch,:qty,'active')",['site'=>$wasteSite,'product'=>$line['product_id'],'type'=>$line['waste_type_id'],'batch'=>$b['id'],'qty'=>$line['quantity_kg']]);$this->query("UPDATE production_batches SET product_id=:product,validated_by=:user,additional_approved_by=CASE WHEN status='pending_additional_approval' THEN :user2 ELSE additional_approved_by END,additional_approved_at=CASE WHEN status='pending_additional_approval' THEN NOW() ELSE additional_approved_at END,status='validated' WHERE id=:id",['product'=>$flourProduct,'user'=>$user['id'],'user2'=>$user['id'],'id'=>$b['id']]);$this->query("UPDATE machine_feeds SET status='validated',ended_at=:ended WHERE id=:id",['ended'=>$b['ended_at'],'id'=>$b['machine_feed_id']]);require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('OF',$b['site_id'],'production_batches',$b['id'],'validated',$b['ended_at'],$user);$this->logActivity('validate_production','production','production_batches',$b['id'],'Validation atomique farine non emballée et déchets par type.',$b,['status'=>'validated','stock_movement_id'=>$movement],$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public static function version(array $b){return hash('sha256',json_encode(array_intersect_key($b,array_flip(['id','status','output_quantity_kg','waste_quantity_kg','ended_at','results_submitted_at','variance_justification']))));}
 private function lockBatch($id){return$this->query('SELECT * FROM production_batches WHERE id=:id AND deleted_at IS NULL FOR UPDATE',['id'=>$id])->fetch();}
 private function productId($code){$r=$this->query('SELECT id FROM products WHERE code=:code AND deleted_at IS NULL LIMIT 1',['code'=>$code])->fetch();if(!$r)throw new RuntimeException('Produit requis introuvable: '.$code);return$r['id'];}
 private function siteId($code){$r=$this->query("SELECT id FROM sites WHERE code=:code AND status='active' AND deleted_at IS NULL LIMIT 1",['code'=>$code])->fetch();if(!$r)throw new RuntimeException('Site requis introuvable: '.$code);return(int)$r['id'];}
 private function latestProductStock($product,$site){$r=$this->query('SELECT stock_after_kg FROM stock_movements WHERE product_id=:product AND site_id=:site AND deleted_at IS NULL ORDER BY movement_at DESC,id DESC LIMIT 1',['product'=>$product,'site'=>$site])->fetch();return$r?(float)$r['stock_after_kg']:0;}
}
